try {
  risky();
  return 1;
} catch (err) {
  console.error(err);
  return 0;
} finally {
  cleanup();
}

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.name = 'HttpError';
    this.status = status;
  }
}

try {
  asyncTask(); // not awaited — rejection escapes
} catch (e) {
  // may not run
}

try {
  await asyncTask();
} catch (e) {
  // handles rejection
}

try {
  await fetchInvoice(id);
} catch (err) {
  throw new Error(`Failed to load invoice ${id}`, { cause: err });
}
